files = ['router.py', 'search.py', 'auth.py', 'logger.py', 'client.py', 'export.py', 'queue.py', 'schema.py', 'parser.py', 'eval.py', 'billing.py', 'codec.py', 'cache.py', 'import.py', 'worker.py', 'index.py', 'metrics.py', 'server.py']
results = [git_last_commit(f) for f in files]
